State the model sees, and state it doesn’t
Agents have two kinds of state and conflating them is the usual source of confusion. Transcript is the dialogue: literally the list of messages the model conditions on. AgentState is the scaffold’s own bookkeeping — how many turns have elapsed, how much budget is left — which the model never sees except as one sentence of prompt.
@dataclass
class Transcript:
    """Dialogue state -- the exact message list handed to the model."""

    messages: list[dict] = field(default_factory=list)

    def user(self, content: str) -&gt; None:
        self.messages.append({"role": "user", "content": content})

    def assistant(self, content: str) -&gt; None:
        self.messages.append({"role": "assistant", "content": content})

    def observation(self, content: str) -&gt; None:
        # Tool results re-enter as user turns: the chat schema has no separate
        # "environment" role, so the observation is framed as one.
        self.messages.append({"role": "user", "content": f"OBSERVATION: {content}"})

    def as_messages(self) -&gt; list[dict]:
        return list(self.messages)

@dataclass
class AgentState:
    """Scaffold state. The model never sees this except as a budget line."""

    turn: int = 0
    max_turns: int = 6
    tool_calls: int = 0
    max_tool_calls: int = 4
    memory: dict[str, Any] = field(default_factory=dict)

    def budget_line(self) -&gt; str:
        left = self.max_turns - self.turn
        return f"You have {left} turn(s) left. Finish before they run out."
The chat schema has no role for “the environment”, so a tool result has to re-enter as a user turn labelled OBSERVATION:. That is a workaround, not a principle, and it is worth knowing it’s there. The memory dict is the seed of everything an agent framework would later grow: right now nothing reads it back.

Tool errors are observations, not exceptions
A tool is a Python function plus a sentence describing it, because the model can only choose a tool it has been told about. The registry holds both, and its one real design decision is in execute:
@dataclass
class Tool:
    """A callable the model may invoke, plus the text describing it."""

    name: str
    description: str
    args: dict[str, str]  # arg name -&gt; type, purely for the prompt
    fn: Callable[..., str]

    def spec(self) -&gt; str:
        signature = ", ".join(f"{k}: {v}" for k, v in self.args.items())
        return f"  {self.name}({signature}) -- {self.description}"

@dataclass
class ToolRegistry:
    """Holds the tools and runs them. Never raises into the agent loop.

    Every failure mode -- unknown tool name, wrong argument names, an
    exception inside the tool itself -- comes back as an observation string.
    A crashed tool is information the policy can act on, not a bug in the
    scaffold, so the loop keeps running and the model gets told what broke.
    """

    tools: dict[str, Tool] = field(default_factory=dict)

    def add(self, tool: Tool) -&gt; "ToolRegistry":
        self.tools[tool.name] = tool
        return self

    def specs(self) -&gt; str:
        if not self.tools:
            return "  (none)"
        return "\n".join(t.spec() for t in self.tools.values())

    def execute(self, name: str, args: dict) -&gt; str:
        tool = self.tools.get(name)
        if tool is None:
            known = ", ".join(self.tools) or "none"
            return f"ERROR: no tool named {name!r}. Available tools: {known}."
        try:
            return str(tool.fn(**args))
        except TypeError as exc:
            expected = ", ".join(tool.args) or "no arguments"
            return f"ERROR: bad arguments for {name} (expects {expected}): {exc}"
        except Exception as exc:
            return f"ERROR: {name} raised {type(exc).__name__}: {exc}"
Nothing in there raises. An unknown tool name, wrong argument names, an exception thrown inside the tool itself — all three are caught and returned as an observation string. This is the single most important line of judgement in the file. A crashed tool is not a bug in the scaffold; it is information the policy can act on, and handing it back as text gives the model a chance to correct itself on the next turn. Raise instead, and one malformed argument kills the whole run.
The two tools the examples use are unremarkable, except that calculator parses to an AST and walks a whitelist rather than calling eval — the model writes the expression, so the expression is untrusted input. Note that the whitelist alone is not enough: it blocks arbitrary code, but 9**9**9 is four perfectly legal nodes that would hang the process, so cost needs bounding separately.
def _eval_node(node: ast.AST) -&gt; float:
    """Evaluate a whitelisted arithmetic AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _BINOPS:
        left, right = _eval_node(node.left), _eval_node(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) &gt; _MAX_EXPONENT:
            raise ValueError(f"exponent {right} exceeds the limit of {_MAX_EXPONENT}")
        return _BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARYOPS:
        return _UNARYOPS[type(node.op)](_eval_node(node.operand))
    raise ValueError(f"unsupported syntax: {type(node).__name__}")

def calculator(expr: str) -&gt; str:
    """Evaluate an arithmetic expression exactly, without `eval`."""
    # `^` means xor in Python but exponentiation in maths notation, and models
    # write the maths one. Translate it rather than failing on it.
    cleaned = expr.replace("^", "**")
    value = _eval_node(ast.parse(cleaned, mode="eval"))
    # `/` always yields a float, so an exact result reads as "2341.0" and the
    # model then feeds that string to a tool wanting an integer. Narrow it.
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    return f"{expr} = {value}"

def is_prime(n: int) -&gt; str:
    """Trial-divide to decide primality."""
    n = int(n)
    if n &lt; 2:
        return f"{n} is not prime"
    factor = next((d for d in range(2, int(n**0.5) + 1) if n % d == 0), None)
    if factor is None:
        return f"{n} is prime"
    return f"{n} is not prime (divisible by {factor})"
Both tools return strings, because a string is what has to go back into the transcript. That leaves the harder direction: turning the model’s string into a typed action.

Parsing is where the contract is actually enforced
The prompt asks for one of two shapes. Nothing makes the model comply, so parse is where we find out:
def parse(text: str) -&gt; Action:
    """Extract a tool call or a final answer from raw model output.

    This is where the contract with the model is actually enforced. The model
    was *asked* for a format; nothing guarantees it complied. A violation is
    an expected event, so it returns a ParseError value rather than raising --
    the loop feeds it back and lets the policy correct itself.
    """
    thought_match = _THOUGHT_RE.search(text)
    thought = thought_match.group(1).strip() if thought_match else ""

    action_match = _ACTION_RE.search(text)
    if action_match and action_match.group(1).strip().lower() in _NULL_ACTIONS:
        action_match = None

    if action_match:
        input_match = _INPUT_RE.search(text)
        if not input_match:
            return ParseError(
                "ACTION was given without a valid ACTION_INPUT line. "
                "ACTION_INPUT must be a single-line JSON object."
            )
        try:
            args = json.loads(input_match.group(1))
        except json.JSONDecodeError as exc:
            return ParseError(f"ACTION_INPUT was not valid JSON: {exc}")
        if not isinstance(args, dict):
            return ParseError("ACTION_INPUT must be a JSON object, not a scalar.")
        return ToolCall(name=action_match.group(1), args=args, thought=thought)

    final_match = _FINAL_RE.search(text)
    if final_match:
        return Final(answer=final_match.group(1).strip(), thought=thought)

    return ParseError(
        "Output matched neither form. Emit either ACTION plus ACTION_INPUT, "
        "or FINAL followed by your answer."
    )
The _NULL_ACTIONS set is not defensive programming for its own sake — it is a bug this post actually hit. Told to reply in “exactly one of two forms”, Llama 3.3 routinely emits both, filling the unused action slot with ACTION: None beside a perfectly good FINAL: line. The first version of this loop read that as a malformed tool call and burned four of its six turns arguing with the model before it gave in. Treating the null word as “no action” fixed it, and the prompt now says explicitly not to write the line. Both halves were needed.
Note that a genuine violation returns a ParseError value rather than raising, for the same reason tool failures do: in a stochastic system, malformed output is a normal event on the happy path, not an exception.

Tool arguments arrive as fragments of a JSON object
Here’s where delivery stops being cosmetic.
A tool, in this API, is a function you describe to the model — a name, a sentence about what it does, and a schema for its arguments. The model never runs it. It hands back the name it wants called and the arguments it wants passed, then waits for you to run the thing and send the result. So the arguments are the payload: get them wrong and you call the wrong function with the wrong values.
They arrive as a tool_use block whose input is a JSON object. Streamed, that object comes as input_json_delta events carrying a partial_json field — and partial is meant literally. These are substrings of the serialised JSON, chopped wherever the boundary fell:
{"type":"input_json_delta","partial_json":"{\"location\":"}
{"type":"input_json_delta","partial_json":" \"San"}
{"type":"input_json_delta","partial_json":" Francisc"}
{"type":"input_json_delta","partial_json":"o, CA\"}"}
{"location": is not JSON. Neither is o, CA"}. The obvious loop — parse each delta as it arrives — fails on every fragment, and not even consistently enough to catch reliably: a fragment can occasionally be valid JSON meaning something entirely different from the document it belongs to.






Concatenate first, parse once



Append each partial_json to a buffer keyed by the block’s index, and call json.loads() only after that block’s content_block_stop. The contract is about the assembled object: tool_use.input is always an object in the final message, even though every delta is a string.


Better still, don’t hand-roll it: get_final_message() does the accumulation and hands back a parsed input dict. That’s the real reason to prefer the SDK helper over the raw event iterator whenever tools are in play.

Peeling bits keeps everything, so it inverts
Start with a step that takes a piece off and keeps it. The first example turns a whole number into its binary digits. At each step it takes the remainder on division by two — the last digit of the binary form, what computing calls the least-significant bit — records it, and hands the halved number back to itself. The base case is zero, which produces the empty list and stops. Its partner, from_binary, does the same walk in reverse.


Code
def to_binary(n: int) -&gt; list[int]:
    if n == 0:
        return []
    return [n % 2] + to_binary(n // 2)


def from_binary(bits: list[int]) -&gt; int:
    if not bits:
        return 0
    return bits[0] + 2 * from_binary(bits[1:])


to_binary(13), from_binary(to_binary(13)), from_binary(to_binary(13)) == 13


([1, 0, 1, 1], 13, True)


It inverts cleanly because every recursive step keeps exactly the information needed to undo itself: the bit it just produced, plus a smaller version of the same problem. Nothing is merged or thrown away, and the base case — [], meaning “done” — is never confusable with an in-progress result. Rebuild bit by bit, in reverse order, and you are back where you started.
So to_binary is a bijection: a perfect pairing, each input matched to exactly one output and each output to exactly one input. That claim needs its domain stated to be true. The pairing runs between the non-negative integers and the bit lists this function can actually produce, which are the ones with no wasted zero on the end; hand from_binary a list from outside that set and you get an answer with no partner to go back to.
None of that came from the recursion, though, and the next function proves it by keeping the recursion and changing one operator.

2 Invertible case: binary digits
to_binary converts a non-negative integer to bits. Each step records \(n \bmod 2\) and recurses on \(n // 2\). The base case \(n = 0\) returns [].
from_binary walks the same structure in reverse.


Code
def to_binary(n: int) -&gt; list[int]:
    if n == 0:
        return []
    return [n % 2] + to_binary(n // 2)


def from_binary(bits: list[int]) -&gt; int:
    if not bits:
        return 0
    return bits[0] + 2 * from_binary(bits[1:])


to_binary(13), from_binary(to_binary(13)), from_binary(to_binary(13)) == 13


([1, 0, 1, 1], 13, True)


Each step keeps the bit it produced plus a smaller instance of the same problem. The base case [] is not confusable with a partial result.
On its actual image — bit lists with no trailing zero — to_binary is a bijection. from_binary on a list outside that image returns a number with no matching to_binary preimage.

4 Batches API
Each judged case is an API call. The Batches API submits all cases as one job, polls until completion, and bills at half per-token price.
Each request carries a custom_id tying results back to cases:

import time

from anthropic.types.message_create_params import MessageCreateParamsNonStreaming
from anthropic.types.messages.batch_create_params import Request

batch = client.messages.batches.create(
    requests=[
        Request(
            custom_id=case["id"],
            params=MessageCreateParamsNonStreaming(
                model="claude-opus-5",
                max_tokens=16000,
                messages=[
                    {
                        "role": "user",
                        "content": RUBRIC.format(
                            context=case["context"], answer=case["answer"]
                        ),
                    }
                ],
                output_config={
                    "format": {
                        "type": "json_schema",
                        "schema": Verdict.model_json_schema(),
                    }
                },
            ),
        )
        for case in CASES
    ]
)

while client.messages.batches.retrieve(batch.id).processing_status != "ended":
    time.sleep(30)

Batch path differences:

Uses output_config.format with raw JSON schema (Verdict.model_json_schema()), not parse()’s output_format=.
extra="forbid" on the Pydantic model sets additionalProperties: false, required by the API’s strict schema subset.

Results return in completion order, not submission order. Look up by custom_id:

verdicts = {}
for result in client.messages.batches.results(batch.id):
    if result.result.type == "errored":
        raise RuntimeError(f"{result.custom_id}: {result.result.error}")
    if result.result.type != "succeeded":
        raise RuntimeError(f"{result.custom_id}: {result.result.type}")
    message = result.result.message
    if message.stop_reason != "end_turn":
        raise RuntimeError(f"{result.custom_id}: stopped on {message.stop_reason}")
    text = next((b.text for b in message.content if b.type == "text"), None)
    if text is None:
        raise RuntimeError(f"{result.custom_id}: completed turn with no text block")
    verdicts[result.custom_id] = Verdict.model_validate_json(text)

labels = {case["id"]: case["label"] for case in CASES}
pass_rate = sum(v.verdict == "pass" for v in verdicts.values()) / len(verdicts)
agreement = sum(verdicts[i].verdict == labels[i] for i in labels) / len(labels)

succeeded means transport success, not usable content. Check stop_reason == "end_turn"; refusals and truncated replies can still arrive under succeeded.
Plausible output on six cases:
pass rate                   0.67
agreement with labels       0.83  (5/6)
disagreement                refund-window-invented-sla: judged pass, labelled fail

5 Tool argument fragments
A tool is a function description (name, description, argument schema). The model returns the name and arguments; your code executes the function.
Streamed tool arguments arrive as input_json_delta events with partial_json — literal substrings of the serialized JSON:
{"type":"input_json_delta","partial_json":"{\"location\":"}
{"type":"input_json_delta","partial_json":" \"San"}
{"type":"input_json_delta","partial_json":" Francisc"}
{"type":"input_json_delta","partial_json":"o, CA\"}"}
Individual fragments are not valid JSON. Parsing each delta as it arrives fails; occasional fragments may parse as unrelated valid JSON.






Concatenate first, parse once



Append each partial_json to a buffer keyed by block index. Call json.loads() only after that block’s content_block_stop. The final tool_use.input is always a complete object.


Prefer get_final_message() for parsed input dicts when tools are in play.

3 State
Two state kinds must stay separate:

Transcript — dialogue; the message list the model conditions on.
AgentState — scaffold bookkeeping (turn count, budget); the model sees only what the prompt includes.

@dataclass
class Transcript:
    """Dialogue state -- the exact message list handed to the model."""

    messages: list[dict] = field(default_factory=list)

    def user(self, content: str) -&gt; None:
        self.messages.append({"role": "user", "content": content})

    def assistant(self, content: str) -&gt; None:
        self.messages.append({"role": "assistant", "content": content})

    def observation(self, content: str) -&gt; None:
        # Tool results re-enter as user turns: the chat schema has no separate
        # "environment" role, so the observation is framed as one.
        self.messages.append({"role": "user", "content": f"OBSERVATION: {content}"})

    def as_messages(self) -&gt; list[dict]:
        return list(self.messages)

@dataclass
class AgentState:
    """Scaffold state. The model never sees this except as a budget line."""

    turn: int = 0
    max_turns: int = 6
    tool_calls: int = 0
    max_tool_calls: int = 4
    memory: dict[str, Any] = field(default_factory=dict)

    def budget_line(self) -&gt; str:
        left = self.max_turns - self.turn
        return f"You have {left} turn(s) left. Finish before they run out."
The chat schema has no environment role. Tool results re-enter as user turns prefixed OBSERVATION:. The memory dict is unused in this version.

4 Tool registry
A tool is a Python function plus a description string. The registry holds both; execute is the main design choice:
@dataclass
class Tool:
    """A callable the model may invoke, plus the text describing it."""

    name: str
    description: str
    args: dict[str, str]  # arg name -&gt; type, purely for the prompt
    fn: Callable[..., str]

    def spec(self) -&gt; str:
        signature = ", ".join(f"{k}: {v}" for k, v in self.args.items())
        return f"  {self.name}({signature}) -- {self.description}"

@dataclass
class ToolRegistry:
    """Holds the tools and runs them. Never raises into the agent loop.

    Every failure mode -- unknown tool name, wrong argument names, an
    exception inside the tool itself -- comes back as an observation string.
    A crashed tool is information the policy can act on, not a bug in the
    scaffold, so the loop keeps running and the model gets told what broke.
    """

    tools: dict[str, Tool] = field(default_factory=dict)

    def add(self, tool: Tool) -&gt; "ToolRegistry":
        self.tools[tool.name] = tool
        return self

    def specs(self) -&gt; str:
        if not self.tools:
            return "  (none)"
        return "\n".join(t.spec() for t in self.tools.values())

    def execute(self, name: str, args: dict) -&gt; str:
        tool = self.tools.get(name)
        if tool is None:
            known = ", ".join(self.tools) or "none"
            return f"ERROR: no tool named {name!r}. Available tools: {known}."
        try:
            return str(tool.fn(**args))
        except TypeError as exc:
            expected = ", ".join(tool.args) or "no arguments"
            return f"ERROR: bad arguments for {name} (expects {expected}): {exc}"
        except Exception as exc:
            return f"ERROR: {name} raised {type(exc).__name__}: {exc}"
Nothing raises. Unknown tool names, bad arguments, and in-tool exceptions all return observation strings. The policy can recover on the next turn; raising kills the run.
Example tools:
def _eval_node(node: ast.AST) -&gt; float:
    """Evaluate a whitelisted arithmetic AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _BINOPS:
        left, right = _eval_node(node.left), _eval_node(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) &gt; _MAX_EXPONENT:
            raise ValueError(f"exponent {right} exceeds the limit of {_MAX_EXPONENT}")
        return _BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARYOPS:
        return _UNARYOPS[type(node.op)](_eval_node(node.operand))
    raise ValueError(f"unsupported syntax: {type(node).__name__}")

def calculator(expr: str) -&gt; str:
    """Evaluate an arithmetic expression exactly, without `eval`."""
    # `^` means xor in Python but exponentiation in maths notation, and models
    # write the maths one. Translate it rather than failing on it.
    cleaned = expr.replace("^", "**")
    value = _eval_node(ast.parse(cleaned, mode="eval"))
    # `/` always yields a float, so an exact result reads as "2341.0" and the
    # model then feeds that string to a tool wanting an integer. Narrow it.
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    return f"{expr} = {value}"

def is_prime(n: int) -&gt; str:
    """Trial-divide to decide primality."""
    n = int(n)
    if n &lt; 2:
        return f"{n} is not prime"
    factor = next((d for d in range(2, int(n**0.5) + 1) if n % d == 0), None)
    if factor is None:
        return f"{n} is prime"
    return f"{n} is not prime (divisible by {factor})"

calculator — AST walk with a whitelist, not eval; model-written expressions are untrusted input.
Cost bound — whitelist blocks arbitrary code but not expensive legal expressions (e.g. 9**9**9).
Both tools return strings for transcript insertion.

5 Output parsing
The prompt requests one of two output shapes. Compliance is not guaranteed; parse enforces the contract:
def parse(text: str) -&gt; Action:
    """Extract a tool call or a final answer from raw model output.

    This is where the contract with the model is actually enforced. The model
    was *asked* for a format; nothing guarantees it complied. A violation is
    an expected event, so it returns a ParseError value rather than raising --
    the loop feeds it back and lets the policy correct itself.
    """
    thought_match = _THOUGHT_RE.search(text)
    thought = thought_match.group(1).strip() if thought_match else ""

    action_match = _ACTION_RE.search(text)
    if action_match and action_match.group(1).strip().lower() in _NULL_ACTIONS:
        action_match = None

    if action_match:
        input_match = _INPUT_RE.search(text)
        if not input_match:
            return ParseError(
                "ACTION was given without a valid ACTION_INPUT line. "
                "ACTION_INPUT must be a single-line JSON object."
            )
        try:
            args = json.loads(input_match.group(1))
        except json.JSONDecodeError as exc:
            return ParseError(f"ACTION_INPUT was not valid JSON: {exc}")
        if not isinstance(args, dict):
            return ParseError("ACTION_INPUT must be a JSON object, not a scalar.")
        return ToolCall(name=action_match.group(1), args=args, thought=thought)

    final_match = _FINAL_RE.search(text)
    if final_match:
        return Final(answer=final_match.group(1).strip(), thought=thought)

    return ParseError(
        "Output matched neither form. Emit either ACTION plus ACTION_INPUT, "
        "or FINAL followed by your answer."
    )
_NULL_ACTIONS handles a observed bug: Llama 3.3 often emits ACTION: None alongside a valid FINAL: line. Treating null tokens as “no action” fixed wasted turns.
Genuine violations return a ParseError value, not an exception — malformed output is a normal event on the happy path.
